begin;
create temp table _had_note on commit drop as select id from public.areas where parking_note is not null;
update public.areas set parking_note='Drive about 6.3 miles up Icicle Creek Road and park on the south side of the road, about 200 yards before the base of Icicle Buttress. A trail starts by a large boulder on the roadbank; first crags are ~15 minutes up.' where id='wa_duty_dome_warrior_wall_peek_a_boo_area' and id not in (select id from _had_note);
update public.areas set parking_note='Drive about 6.3 miles up Icicle Creek Road and park on the south side of the road, about 200 yards before the base of Icicle Buttress. A trail starts by a large boulder on the roadbank; first crags are ~15 minutes up.' where path <@ (select path from public.areas where id='wa_duty_dome_warrior_wall_peek_a_boo_area') and id <> 'wa_duty_dome_warrior_wall_peek_a_boo_area' and id not in (select id from _had_note) and parking_note is null and parking_lat is null and id not in ('wa_owl_gore_boulder','wa_rbg_boulder');
update public.areas set parking_note='Park in the large pullout on the right (uphill side) of the Alpine Loop road, about 0.65 mi past the Hideaway parking and marked by the green mile marker 11 sign. Cross the road for the trail. It is a National Forest fee area.' where id='ut_hell_area' and id not in (select id from _had_note);
update public.areas set parking_note='Park in the large pullout on the right (uphill side) of the Alpine Loop road, about 0.65 mi past the Hideaway parking and marked by the green mile marker 11 sign. Cross the road for the trail. It is a National Forest fee area.' where path <@ (select path from public.areas where id='ut_hell_area') and id <> 'ut_hell_area' and id not in (select id from _had_note) and parking_note is null and parking_lat is null;
update public.areas set parking_note='Drive 0.8 mi up Maple Canyon Road from the canyon mouth, where the pavement turns to dirt, and park at one of several roadside pullouts. The land is private; a small donation for parking is requested.' where id='ut_box_canyon' and id not in (select id from _had_note);
update public.areas set parking_note='Drive 0.8 mi up Maple Canyon Road from the canyon mouth, where the pavement turns to dirt, and park at one of several roadside pullouts. The land is private; a small donation for parking is requested.' where path <@ (select path from public.areas where id='ut_box_canyon') and id <> 'ut_box_canyon' and id not in (select id from _had_note) and parking_note is null and parking_lat is null and id not in ('ut_the_box_canyon_ice_climbs');
commit;
